    {
      "rank": 1,
      "ballot_id": "B024",
      "proposed_laureates": [
        "Kenneth J. Schafer",
        "Maciej Lewenstein",
        "Paul B. Corkum"
      ],
      "assessment": {
        "nobel_worthiness": "The recollision picture and its quantum theory gave strong-field physics a remarkably productive framework, explaining high-harmonic generation and enabling attosecond science. It connects an unexpected laser-driven process to new ways of studying matter in time.",
        "attribution": "Corkum's recollision model and the complementary theoretical work of Lewenstein and Schafer are central contributions. The field's later development involved many experimental and theoretical groups, so the prize would need to name a sharply bounded contribution.",
        "maturity": "The ideas have been tested across decades of experiments and have become central to attosecond research.",
        "uncertainties": [
          "The relative credit for the model's key components and their subsequent development is not completely separable."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B065",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks transformed precision measurement, combining exceptional stability with control of systematic effects and opening new tests of fundamental physics.",
        "attribution": "Katori and Ye independently established leading approaches and sustained experimental programs. Their distinct contributions are recognizable, though the broader clock field has many important contributors.",
        "maturity": "The clocks have been repeatedly demonstrated and improved by multiple laboratories over many years.",
        "uncertainties": [
          "The eventual Nobel boundary between these foundational clock advances and later clock developments may be difficult to draw."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B018",
      "proposed_laureates": [
        "Alexei Kitaev",
        "Andrew M. Steane",
        "Peter W. Shor"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction showed how fragile quantum information could, in principle, be protected, changing the foundations and prospects of quantum information physics.",
        "attribution": "Shor and Steane introduced landmark codes, while Kitaev's topological ideas supplied a powerful route to fault tolerance. These are substantial, distinguishable contributions, although the field's foundations are broad.",
        "maturity": "The theory is mature and has guided extensive experiments, with increasingly capable demonstrations of error correction.",
        "uncertainties": [
          "A Nobel citation would need to distinguish foundational codes and topological fault tolerance from the many later advances that made them operational."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B006",
      "proposed_laureates": [
        "Charles L. Kane",
        "Eugene J. Mele",
        "Laurens W. Molenkamp"
      ],
      "assessment": {
        "nobel_worthiness": "The quantum spin Hall effect and topological insulators revealed robust electronic states protected by topology, establishing a major new direction in condensed matter physics.",
        "attribution": "Kane and Mele supplied the theoretical prediction and classification, and Molenkamp's experiments provided crucial confirmation. This theory–experiment attribution is compelling.",
        "maturity": "The original phenomena have been confirmed and the topological framework has been built on across a broad range of materials.",
        "uncertainties": [
          "Some early material realizations were narrow, though the underlying topological ideas proved much broader."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B012",
      "proposed_laureates": [
        "Gerald Gabrielse",
        "Jeffrey Hangst",
        "Stefan Ulmer"
      ],
      "assessment": {
        "nobel_worthiness": "Trapping cold antimatter enables precision comparisons with matter and stringent tests of fundamental symmetries. It combines a striking experimental achievement with a clear physics question.",
        "attribution": "The proposed names represent complementary achievements in antihydrogen trapping and precision measurements. Long-running collaborations and several distinct experimental milestones make individual credit delicate.",
        "maturity": "Antihydrogen has been trapped and studied by multiple teams, while precision tests continue to improve.",
        "uncertainties": [
          "The most consequential CPT comparison may still be developing, and the credit for the full experimental program is distributed."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B005",
      "proposed_laureates": [
        "Antoine Georges",
        "Dieter Vollhardt",
        "Gabriel Kotliar"
      ],
      "assessment": {
        "nobel_worthiness": "Dynamical mean-field theory made strongly correlated electrons tractable in a way that connects microscopic models to real materials, with lasting influence across condensed matter physics.",
        "attribution": "Georges, Vollhardt, and Kotliar are central to developing and systematizing the method. Its foundations were built through several closely related contributions, requiring careful citation.",
        "maturity": "The framework has been used and extended for decades, and its value is established across theory and materials research.",
        "uncertainties": [
          "The work is primarily a theoretical method, and its landmark advances are less readily summarized as one discovery."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B023",
      "proposed_laureates": [
        "Carlton M. Caves",
        "H. Jeff Kimble",
        "Nergis Mavalvala"
      ],
      "assessment": {
        "nobel_worthiness": "Squeezed light enables measurements beyond the standard quantum limit and has made a concrete difference in gravitational-wave detection, linking quantum optics to fundamental astronomy.",
        "attribution": "Caves supplied foundational theory, Kimble advanced experimental quantum optics, and Mavalvala led important application in interferometers. The long path from concept to deployment includes many contributors.",
        "maturity": "Squeezing is well established in optics and has been demonstrated in operating gravitational-wave detectors.",
        "uncertainties": [
          "Roman Schnabel and other groups also made major contributions to the experimental realization, complicating a three-person attribution."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B016",
      "proposed_laureates": [
        "Juan Ignacio Cirac",
        "Peter Zoller",
        "Rainer Blatt"
      ],
      "assessment": {
        "nobel_worthiness": "Trapped ions and ultracold atoms made quantum simulation and computing experimentally concrete, while giving physicists new control over many-body quantum systems.",
        "attribution": "Cirac and Zoller developed influential theoretical proposals, and Blatt's experiments demonstrated key operations. The listed contributions are strong but sit within a large international effort.",
        "maturity": "The platforms and simulations have advanced steadily for decades, with robust demonstrations, though fault-tolerant computing remains unfinished.",
        "uncertainties": [
          "It remains unclear whether the enduring recognition should center on foundational proposals, experimental control, or a specific scientific result from simulation."
        ]
      }
    }
  ]
